float2 complex_mul(float2 factorA, float2 factorB){
   return float2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
}

float2 complex_pow(float2 base, int exponent){
   float2 exponentiation = float2(1,0);
   for(int i = 0; i<exponent; i++){
      exponentiation = complex_mul(base,exponentiation);
   }
   return exponentiation;
}

float2 complex_square(float2 domain){
   return complex_mul(domain,domain);
}

float2 complex_div(float2 numerator, float2 denominator){
   return float2( numerator.x*denominator.x + numerator.y*denominator.y,
                  numerator.y*denominator.x - numerator.x*denominator.y)/
          (denominator.x*denominator.x + denominator.y*denominator.y);
}

float2 uv_aspect(float2 uvo, float2 uvm, float2 aspectr, float2 motion_scale){
   return 0.5 + (lerp(uvo,uvm,motion_scale)-0.5)*aspectr;
}

float2 uv_scale(float2 domain, float2 center, float2 scale){
   return center + (domain-center)*scale;
}

float2 uv_torus_mirror(float2 domain, float cutoff){
   return 0.5 + (1.0 - abs( frac( domain * 0.5 ) * 2 - 1.0 )-0.5)*cutoff;
}

bool mask_rectangle(float2 domain, float2 position, float2 dimensions){
   return (domain.x>position.x-dimensions.x)*(domain.x<position.x+dimensions.x)*
          (domain.y>position.y-dimensions.y)*(domain.y<position.y+dimensions.y);
}

bool mask_circle(float2 domain, float2 position, float radius){
   return length(domain-position)<radius;
}

bool mask_spiral_logarithmic(float2 domain, float2 center, int fins, float thickness, float spiral_factor, float zoom){
   float2 c = domain - center;
   float rad_hq = length(c);
   float ang_hq = atan2(c.x,c.y);

   return frac(fins*ang_hq*M_INV_PI_2 + spiral_factor*log(1/rad_hq)+zoom)<thickness;
}

float figure_spiral_logarithmic(float2 domain, float2 center, int fins, float thickness, float spiral_factor, float zoom){
   float2 c = domain - center;
   float rad_hq = length(c);
   float ang_hq = atan2(c.x,c.y);

   return saturate(1-uv_torus_mirror(fins*ang_hq*M_INV_PI_2*2 + spiral_factor*log(1/rad_hq)+zoom,0.999)/thickness);
}

float figure_circle(float2 domain, float2 position, float radius){
   return saturate(1-length(domain-position)/radius);
}

float figure_orb_of_3(float2 domain){
   float2 help_uv = domain;
   help_uv = uv_scale(help_uv, 0.5, 4);
   help_uv = 0.5 + complex_pow(help_uv-0.5,3);
   help_uv = uv_scale(help_uv, 0.5, 1);

   return figure_circle(help_uv,float2(0,0.5),0.6);
}

float figure_orb_of_spiral_of_3(float2 domain){
   float2 help_uv = domain;
   help_uv = uv_scale(help_uv, 0.5, 0.33);
   help_uv = 0.5 + complex_pow(help_uv-0.5,3);
   help_uv = uv_scale(help_uv, 0.5, 640);

   return figure_spiral_logarithmic(help_uv, float2(0.4,0.5), -4, 1, 2, -time*4);
}

